// Ported from the public AIcss React source.
// Source: https://www.aicss.dev/components/inline-citations
"use client"

import styles from "./inline-citations.module.css";

type CiteRef = { n: number; label: string; host: string; url: string };

const TEXT =
  "Transformers scale well with data and compute[1], though attention is quadratic in sequence length[2].";
const REFS: CiteRef[] = [
  { n: 1, label: "Attention Is All You Need", host: "arxiv.org", url: "https://arxiv.org/abs/1706.03762" },
  { n: 2, label: "Efficient Transformers: A Survey", host: "arxiv.org", url: "https://arxiv.org/abs/2009.06732" },
];

function CiteArrow() {
  return (
    <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M4.5 10.5 12 3m0 0 7.5 7.5M12 3v18" />
    </svg>
  );
}

export function InlineCitations({
  text = TEXT,
  refs = REFS,
}: {
  text?: string;
  refs?: CiteRef[];
}) {
  // Markers like [1] in the text become small numbered chips that link to
  // the source and reveal the reference name in a tooltip on hover.
  const parts = text.split(/(\[\d+\])/g);
  return (
    <div className={styles.citeProse}>
      <p>
        {parts.map((part, i) => {
          const m = part.match(/^\[(\d+)\]$/);
          if (!m) return <span key={i}>{part}</span>;
          const r = refs.find((x) => x.n === Number(m[1]));
          return r ? (
            <span key={i} className={styles.citeTip}>
              <a className={styles.citeMark} href={r.url} target="_blank" rel="noreferrer">{r.n}</a>
              <span className={styles.citeTipBox} role="tooltip">{r.label}</span>
            </span>
          ) : (
            <span key={i} className={styles.citeMark}>{m[1]}</span>
          );
        })}
      </p>
      <div className={styles.citeFooter}>
        {refs.map((r) => (
          <a key={r.n} className={styles.citeRef} href={r.url} target="_blank" rel="noreferrer">
            <span className={styles.citeMark}>{r.n}</span>
            <span className={styles.citeRefLabel}>{r.label}</span>
            <span className={styles.citeSep}>·</span>
            <span className={styles.citeRefHost}>{r.host}</span>
            <span className={styles.citeArrow} aria-hidden><CiteArrow /></span>
          </a>
        ))}
      </div>
    </div>
  );
}

/* Ported from https://www.aicss.dev/components/inline-citations */
.citeProse { font-size: 0.875rem; line-height: 1.1875rem; color: var(--foreground); }
/* In a browser without anchor positioning the paragraph places the tooltip.
   Centred on its mark with `left: 50%`, the tooltip ran past the card's edge
   for a mark near that edge and sat on the line above the mark. From the
   paragraph it stays inside the text's width and above its first line, and a
   long title wraps. [BD-1071] */
.citeProse p { position: relative; margin: 0; }
.citeMark { display: inline-flex; align-items: center; justify-content: center; width: 0.75rem; height: 0.75rem; flex: none; border-radius: 0.25rem; background: var(--muted); color: var(--muted-foreground); font-size: 0.5625rem; font-weight: 600; line-height: 1; vertical-align: 0.34375rem; margin: 0 0.125rem; }
a.citeMark { cursor: pointer; text-decoration: none; transition: color 0.15s, background 0.15s; }
@media (hover: hover) and (pointer: fine) {
a.citeMark:hover { color: var(--foreground); background: var(--border); } }
.citeTip { display: inline; }
/* The hidden tooltip makes no box. At opacity 0 alone it still added to the
   page's scroll width, so a citation near the right edge made a phone scroll
   sideways. The fade stays in a browser that can transition display. [BD-1071] */
.citeTipBox { position: absolute; inset-inline-start: 0; bottom: calc(100% + 0.375rem); box-sizing: border-box; max-width: 100%; transform: translateY(0.0625rem); font-size: 0.625rem; line-height: 1.2; font-weight: 500; color: oklch(1 0 0 / 0.9); background: oklch(0.2308 0 0 / 0.6); -webkit-backdrop-filter: blur(0.375rem); backdrop-filter: blur(0.375rem); padding: 0.25rem 0.3125rem; border-radius: 0.375rem; pointer-events: none; display: none; opacity: 0; filter: blur(0.125rem); transition: opacity 0.15s ease, transform 0.15s ease, filter 0.15s ease, display 0.15s allow-discrete; z-index: 1000; }
@media (hover: hover) and (pointer: fine) {
.citeTip:hover .citeTipBox, .citeTip:focus-within .citeTipBox { display: block; opacity: 1; filter: blur(0); transform: translateY(0); }
@starting-style {
.citeTip:hover .citeTipBox, .citeTip:focus-within .citeTipBox { opacity: 0; filter: blur(0.125rem); transform: translateY(0.0625rem); } } }
/* Where the browser can anchor, each tooltip sits centred over its own mark.
   The prose block holds it between its left and right edges, a gap keeps it
   off the mark's own line, and it goes below the mark when the room above is
   too small. The scope stops every tooltip from attaching to the last mark.
   The paragraph must not place it here, or a first-line mark's tooltip covers
   its own line. [BD-1071] */
@supports (anchor-name: --cite-mark) and (position-area: top) {
.citeProse { position: relative; }
.citeProse p { position: static; }
.citeTip { anchor-name: --cite-mark; anchor-scope: --cite-mark; }
.citeTipBox { position-anchor: --cite-mark; inset: auto; position-area: top; position-try-fallbacks: flip-block; width: max-content; max-width: 100%; margin-block: 0.375rem; white-space: normal; } }
.citeFooter { display: flex; flex-direction: column; gap: 0.375rem; margin-top: 0.75rem; padding-top: 0.625rem; border-top: 0.0625rem solid var(--border); }
.citeRef { display: flex; align-items: center; gap: 0.375rem; font-size: 0.75rem; line-height: 1.125rem; color: var(--muted-foreground); min-width: 0; text-decoration: none; cursor: pointer; }
.citeRef .citeMark { margin: 0; }
.citeRefLabel { color: var(--foreground); font-weight: 450; flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.citeSep { color: var(--muted-foreground); flex: none; }
.citeRefHost { color: var(--muted-foreground); flex: none; white-space: nowrap; transition: color 0.16s; }
.citeArrow { display: inline-flex; flex: none; margin-left: -0.125rem; color: var(--muted-foreground); opacity: 0; transform: rotate(45deg) translate(0, 0.125rem); transition: opacity 0.16s, transform 0.22s; pointer-events: none; }
@media (hover: hover) and (pointer: fine) {
.citeRef:hover .citeArrow { opacity: 1; transform: rotate(45deg) translate(0, 0); } }
@media (hover: hover) and (pointer: fine) {
.citeRef:hover .citeRefHost { color: var(--foreground); } }
@media (prefers-reduced-motion: reduce) {
 a.citeMark,
.citeTipBox,
.citeRefHost,
.citeArrow { animation: none !important; transition-duration: 0.01ms !important; } }
